/**
 * Preview environments: Applications generated by pull-request generators (one per open pull
 * request). Pull request details are read, in order, from the Application's labels and
 * annotations (any prefix; key names like "pr-number", "branch", "head-sha"), then from its name
 * ("…-pr-42") and source revision. Templates should copy {{number}}, {{branch}} and
 * {{head_sha}} into labels or annotations for reliable results (see ui.md).
 */
import type { ApplicationSet } from '../../api/types';
import { flattenGenerators, type Generator } from './model';

type PullRequestGenerator = NonNullable<Generator['pullRequest']>;

const NUMBER_KEYS = ['prnumber', 'pullrequest', 'pullrequestnumber', 'pr', 'number', 'mergerequest', 'mrnumber', 'mr'];
const BRANCH_KEYS = ['branch', 'prbranch', 'sourcebranch', 'headbranch', 'headref'];
const SHA_KEYS = ['headsha', 'sha', 'commit', 'headcommit', 'commitsha'];
const URL_KEYS = ['prurl', 'pullrequesturl', 'url'];
const SHA_RE = /^[0-9a-f]{7,40}$/i;

function normalizedKey(key: string): string {
  return (key.split('/').pop() ?? key).toLowerCase().replace(/[^a-z0-9]/g, '');
}

/** What previewEnvironment reads from an Application. */
export interface PreviewSubject {
  metadata: { name?: string | undefined; labels?: Record<string, string> | undefined; annotations?: Record<string, string> | undefined };
  spec?: { source?: { targetRevision?: string | undefined } | undefined; sources?: { targetRevision?: string | undefined }[] | undefined } | undefined;
}

function lookup(app: PreviewSubject, keys: readonly string[], accept: (v: string) => boolean): string | undefined {
  const entries = [...Object.entries(app.metadata.labels ?? {}), ...Object.entries(app.metadata.annotations ?? {})];
  for (const wanted of keys) {
    const hit = entries.find(([k, v]) => normalizedKey(k) === wanted && accept(v));
    if (hit) return hit[1];
  }
  return undefined;
}

export interface PullRequestSource {
  provider: string;
  /** owner/repo, project, ... as configured. */
  repository: string;
  labels: string[];
  filters: string[];
  requeueAfterSeconds: number;
  /** Builds the web URL of a pull request number, when the provider allows it. */
  urlFor: (n: string) => string | null;
}

function trimSlash(url: string): string {
  return url.replace(/\/+$/, '');
}

function webBase(api: string | undefined, fallback: string, strip: RegExp): string {
  if (!api) return fallback;
  try {
    const u = new URL(api);
    if (u.protocol !== 'https:' && u.protocol !== 'http:') return fallback;
    return trimSlash(`${u.origin}${u.pathname.replace(strip, '')}`);
  } catch {
    return fallback;
  }
}

const enc = encodeURIComponent;

export function pullRequestSource(gen: PullRequestGenerator): PullRequestSource {
  const filters = (gen.filters ?? []).map((f) =>
    [f.branchMatch && `branch ~ ${f.branchMatch}`, f.targetBranchMatch && `target ~ ${f.targetBranchMatch}`, f.titleMatch && `title ~ ${f.titleMatch}`]
      .filter(Boolean)
      .join(', '),
  );
  const requeueAfterSeconds = gen.requeueAfterSeconds ?? 1800;
  const base = { filters: filters.filter((f) => f !== ''), requeueAfterSeconds };
  if (gen.github) {
    const g = gen.github;
    const web = webBase(g.api, 'https://github.com', /\/api\/v3\/?$/);
    return { ...base, provider: 'GitHub', repository: `${g.owner}/${g.repo}`, labels: g.labels ?? [], urlFor: (n) => `${web}/${enc(g.owner)}/${enc(g.repo)}/pull/${enc(n)}` };
  }
  if (gen.gitlab) {
    const g = gen.gitlab;
    const web = webBase(g.api, 'https://gitlab.com', /\/api\/v4\/?$/);
    // A numeric project ID cannot be turned into a web path.
    const linkable = g.project.includes('/');
    return {
      ...base,
      provider: 'GitLab',
      repository: g.project,
      labels: g.labels ?? [],
      urlFor: (n) => (linkable ? `${web}/${g.project.split('/').map(enc).join('/')}/-/merge_requests/${enc(n)}` : null),
    };
  }
  if (gen.gitea) {
    const g = gen.gitea;
    const web = webBase(g.api, '', /\/api\/v1\/?$/);
    return {
      ...base,
      provider: 'Gitea',
      repository: `${g.owner}/${g.repo}`,
      labels: g.labels ?? [],
      urlFor: (n) => (web ? `${web}/${enc(g.owner)}/${enc(g.repo)}/pulls/${enc(n)}` : null),
    };
  }
  if (gen.bitbucket) {
    const g = gen.bitbucket;
    return {
      ...base,
      provider: 'Bitbucket Cloud',
      repository: `${g.owner}/${g.repo}`,
      labels: [],
      urlFor: (n) => `https://bitbucket.org/${enc(g.owner)}/${enc(g.repo)}/pull-requests/${enc(n)}`,
    };
  }
  if (gen.bitbucketServer) {
    const g = gen.bitbucketServer;
    const web = webBase(g.api, '', /\/rest\/?.*$/);
    return {
      ...base,
      provider: 'Bitbucket Data Center',
      repository: `${g.project}/${g.repo}`,
      labels: [],
      urlFor: (n) => (web ? `${web}/projects/${enc(g.project)}/repos/${enc(g.repo)}/pull-requests/${enc(n)}` : null),
    };
  }
  if (gen.azuredevops) {
    const g = gen.azuredevops;
    const web = webBase(g.api, 'https://dev.azure.com', /\/+$/);
    return {
      ...base,
      provider: 'Azure DevOps',
      repository: `${g.organization}/${g.project}/${g.repo}`,
      labels: g.labels ?? [],
      urlFor: (n) => `${web}/${enc(g.organization)}/${enc(g.project)}/_git/${enc(g.repo)}/pullrequest/${enc(n)}`,
    };
  }
  return { ...base, provider: 'SCM provider', repository: '', labels: [], urlFor: () => null };
}

export function pullRequestSources(set: ApplicationSet): PullRequestSource[] {
  return flattenGenerators(set.spec.generators)
    .map((g) => g.pullRequest)
    .filter((g): g is PullRequestGenerator => g !== undefined)
    .map(pullRequestSource);
}

export interface PreviewEnvironment {
  number?: string | undefined;
  branch?: string | undefined;
  headSha?: string | undefined;
  url?: string | null | undefined;
}

function primarySource(app: PreviewSubject) {
  return app.spec?.source ?? app.spec?.sources?.[0];
}

/** Pull request details of one generated Application (see the module comment). */
export function previewEnvironment(app: PreviewSubject, source: PullRequestSource | undefined): PreviewEnvironment {
  const number = lookup(app, NUMBER_KEYS, (v) => /^\d+$/.test(v)) ?? /(?:^|[-_.])(?:pr|mr|pull)-?(\d+)(?:$|[-_.])/i.exec(app.metadata.name ?? '')?.[1];
  const revision = primarySource(app)?.targetRevision ?? '';
  const headSha = lookup(app, SHA_KEYS, (v) => SHA_RE.test(v)) ?? (SHA_RE.test(revision) ? revision : undefined);
  const branch = lookup(app, BRANCH_KEYS, (v) => v.trim() !== '') ?? (revision && !SHA_RE.test(revision) && revision !== 'HEAD' ? revision : undefined);
  const explicitURL = lookup(app, URL_KEYS, (v) => /^https?:\/\//.test(v));
  const url = explicitURL ?? (number && source ? source.urlFor(number) : null);
  return { number, branch, headSha, url };
}

/**
 * Cleanup behavior for preview Applications when their pull request closes (the generator stops
 * returning it).
 */
export function previewCleanupPolicy(set: ApplicationSet): string {
  const policy = set.spec.syncPolicy?.applicationsSync;
  const preserve = set.spec.syncPolicy?.preserveResourcesOnDeletion === true;
  if (policy === 'create-only' || policy === 'create-update') {
    return `Not cleaned up automatically: applicationsSync is ${policy}, so the Application of a closed pull request stays until someone deletes it.`;
  }
  const resources = preserve
    ? 'its deployed resources are kept (preserveResourcesOnDeletion).'
    : 'its deployed resources are deleted with it when the Application has the resources finalizer.';
  return `Deleted when the pull request closes or stops matching the filters (applicationsSync: ${policy ?? 'sync'}); ${resources}`;
}
